"""Dependency-light contracts shared by G1 controller implementations."""

from __future__ import annotations

import math
from dataclasses import dataclass
from enum import Enum
from typing import Protocol

from .config import G1ControllerProfile


def _finite_tuple(values: tuple[float, ...], expected: int, name: str) -> tuple[float, ...]:
    converted = tuple(float(value) for value in values)
    if len(converted) != expected:
        raise ValueError(f"{name} must contain {expected} values")
    if not all(math.isfinite(value) for value in converted):
        raise ValueError(f"{name} contains a non-finite value")
    return converted


@dataclass(frozen=True)
class VelocityCommand:
    """Body-frame velocity command in metres/second and radians/second."""

    linear_xy: tuple[float, float] = (0.0, 0.0)
    angular_z: float = 0.0

    def __post_init__(self) -> None:
        linear = _finite_tuple(tuple(self.linear_xy), 2, "linear_xy")
        angular = float(self.angular_z)
        if not math.isfinite(angular):
            raise ValueError("angular_z must be finite")
        object.__setattr__(self, "linear_xy", linear)
        object.__setattr__(self, "angular_z", angular)


@dataclass(frozen=True)
class TorsoCommand:
    """AMO torso command; FastSAC ignores orientation fields."""

    height_m: float = 0.75
    roll_rad: float = 0.0
    pitch_rad: float = 0.0
    yaw_rad: float = 0.0

    def __post_init__(self) -> None:
        values = (self.height_m, self.roll_rad, self.pitch_rad, self.yaw_rad)
        if not all(math.isfinite(float(value)) for value in values):
            raise ValueError("torso command must be finite")


@dataclass(frozen=True)
class G1State:
    """One G1 low-state sample in Holosoma's scalar-first state layout."""

    base_position: tuple[float, ...]
    quaternion_wxyz: tuple[float, ...]
    joint_positions: tuple[float, ...]
    base_linear_velocity: tuple[float, ...]
    base_angular_velocity: tuple[float, ...]
    joint_velocities: tuple[float, ...]
    projected_gravity: tuple[float, ...] | None = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "base_position", _finite_tuple(self.base_position, 3, "base_position"))
        object.__setattr__(self, "quaternion_wxyz", _finite_tuple(self.quaternion_wxyz, 4, "quaternion_wxyz"))
        object.__setattr__(self, "joint_positions", _finite_tuple(self.joint_positions, 29, "joint_positions"))
        object.__setattr__(
            self,
            "base_linear_velocity",
            _finite_tuple(self.base_linear_velocity, 3, "base_linear_velocity"),
        )
        object.__setattr__(
            self,
            "base_angular_velocity",
            _finite_tuple(self.base_angular_velocity, 3, "base_angular_velocity"),
        )
        object.__setattr__(self, "joint_velocities", _finite_tuple(self.joint_velocities, 29, "joint_velocities"))
        if self.projected_gravity is not None:
            object.__setattr__(
                self,
                "projected_gravity",
                _finite_tuple(self.projected_gravity, 3, "projected_gravity"),
            )

    @classmethod
    def from_holosoma_vector(cls, values: tuple[float, ...]) -> "G1State":
        """Decode ``[pos3, quat4, q29, linear3, angular3, dq29, gravity?]``."""

        flat = tuple(float(value) for value in values)
        expected = 71
        if len(flat) not in (expected, expected + 3):
            raise ValueError(f"Holosoma G1 state must contain {expected} or {expected + 3} values")
        gravity = flat[expected : expected + 3] if len(flat) == expected + 3 else None
        return cls(
            base_position=flat[0:3],
            quaternion_wxyz=flat[3:7],
            joint_positions=flat[7:36],
            base_linear_velocity=flat[36:39],
            base_angular_velocity=flat[39:42],
            joint_velocities=flat[42:71],
            projected_gravity=gravity,
        )

    def holosoma_vector(self) -> tuple[float, ...]:
        """Encode the state using Holosoma's stable low-state ordering."""

        base = (
            self.base_position
            + self.quaternion_wxyz
            + self.joint_positions
            + self.base_linear_velocity
            + self.base_angular_velocity
            + self.joint_velocities
        )
        return base + (() if self.projected_gravity is None else self.projected_gravity)


@dataclass(frozen=True)
class PolicyResult:
    """Full-width target generated by a lower-body policy."""

    joint_targets: tuple[float, ...]
    feedforward_torques: tuple[float, ...]
    raw_action: tuple[float, ...]

    def __post_init__(self) -> None:
        object.__setattr__(self, "joint_targets", _finite_tuple(self.joint_targets, 29, "joint_targets"))
        object.__setattr__(
            self,
            "feedforward_torques",
            _finite_tuple(self.feedforward_torques, 29, "feedforward_torques"),
        )
        raw = tuple(float(value) for value in self.raw_action)
        if not raw or not all(math.isfinite(value) for value in raw):
            raise ValueError("raw_action must be non-empty and finite")
        object.__setattr__(self, "raw_action", raw)


@dataclass(frozen=True)
class LowCommand:
    """One complete 29-joint low-level command."""

    positions: tuple[float, ...]
    velocities: tuple[float, ...]
    feedforward_torques: tuple[float, ...]
    stiffness: tuple[float, ...]
    damping: tuple[float, ...]

    def __post_init__(self) -> None:
        for name in (
            "positions",
            "velocities",
            "feedforward_torques",
            "stiffness",
            "damping",
        ):
            object.__setattr__(self, name, _finite_tuple(getattr(self, name), 29, name))


class ControllerCommand(str, Enum):
    """Discrete commands retained from Holosoma's G1 lifecycle."""

    start = "start"
    stop = "stop"
    initialize = "initialize"
    toggle_walk = "toggle_walk"
    zero_velocity = "zero_velocity"
    stiffness_up = "stiffness_up"
    stiffness_down = "stiffness_down"
    stiffness_up_fine = "stiffness_up_fine"
    stiffness_down_fine = "stiffness_down_fine"
    stiffness_reset = "stiffness_reset"
    kill = "kill"


